import { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Wifi, 
  WifiOff, 
  RefreshCw, 
  CheckCircle, 
  AlertCircle,
  Download,
  Upload,
  Database,
  RotateCcw,
  Clock,
  Zap
} from 'lucide-react';
import { syncService, addSyncListener } from '../lib/syncService';
import { getSyncStatistics } from '../lib/database';

function EnhancedOfflineStatus() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [lastSync, setLastSync] = useState(null);
  const [pendingChanges, setPendingChanges] = useState(0);
  const [syncStatus, setSyncStatus] = useState('idle'); // idle, syncing, success, error
  const [showDetails, setShowDetails] = useState(false);
  const [cacheStatus, setCacheStatus] = useState('unknown');
  const [syncStats, setSyncStats] = useState({});
  const [syncInProgress, setSyncInProgress] = useState(false);

  useEffect(() => {
    // Initialize sync service listener
    const unsubscribe = addSyncListener((syncEvent) => {
      const { event, data, isOnline: online, syncInProgress: inProgress, lastSyncTime } = syncEvent;
      
      setIsOnline(online);
      setSyncInProgress(inProgress);
      
      if (lastSyncTime) {
        setLastSync(lastSyncTime);
      }
      
      switch (event) {
        case 'online':
          setSyncStatus('idle');
          break;
        case 'offline':
          setSyncStatus('idle');
          break;
        case 'sync-start':
          setSyncStatus('syncing');
          break;
        case 'sync-success':
          setSyncStatus('success');
          setTimeout(() => setSyncStatus('idle'), 3000);
          break;
        case 'sync-error':
          setSyncStatus('error');
          setTimeout(() => setSyncStatus('idle'), 5000);
          break;
        case 'sync-end':
          // Status will be set by success/error events
          break;
      }
    });

    // Initial status check
    const initialStatus = syncService.getSyncStatus();
    setIsOnline(initialStatus.isOnline);
    setSyncInProgress(initialStatus.syncInProgress);
    setLastSync(initialStatus.lastSyncTime);

    // Check cache status and sync statistics
    checkCacheStatus();
    loadSyncStatistics();

    // Periodic updates
    const interval = setInterval(() => {
      loadSyncStatistics();
    }, 30000);

    return () => {
      unsubscribe();
      clearInterval(interval);
    };
  }, []);

  const checkCacheStatus = async () => {
    try {
      if ('caches' in window) {
        const cacheNames = await caches.keys();
        if (cacheNames.length > 0) {
          const cache = await caches.open(cacheNames[0]);
          const keys = await cache.keys();
          setCacheStatus(keys.length > 0 ? 'ready' : 'empty');
        } else {
          setCacheStatus('empty');
        }
      } else {
        setCacheStatus('unsupported');
      }
    } catch (error) {
      console.error('Error checking cache status:', error);
      setCacheStatus('error');
    }
  };

  const loadSyncStatistics = async () => {
    try {
      const stats = await getSyncStatistics();
      setSyncStats(stats);
      setPendingChanges(stats.pendingOperations + stats.recordsNeedingSync);
    } catch (error) {
      console.error('Error loading sync statistics:', error);
    }
  };

  const openDB = () => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('award_system_sync', 1);
      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
    });
  };

  const handleManualSync = async () => {
    if (!isOnline || syncInProgress) {
      return;
    }

    try {
      await syncService.forceSync();
      await loadSyncStatistics();
    } catch (error) {
      console.error('Manual sync failed:', error);
    }
  };

  const clearCache = async () => {
    try {
      if ('serviceWorker' in navigator) {
        const registration = await navigator.serviceWorker.ready;
        const messageChannel = new MessageChannel();
        
        messageChannel.port1.onmessage = (event) => {
          if (event.data.success) {
            setCacheStatus('empty');
            window.location.reload();
          }
        };

        registration.active.postMessage(
          { type: 'CLEAR_CACHE' },
          [messageChannel.port2]
        );
      }
    } catch (error) {
      console.error('Clear cache failed:', error);
    }
  };

  const getStatusColor = () => {
    if (!isOnline) return 'bg-red-500';
    if (pendingChanges > 0) return 'bg-yellow-500';
    return 'bg-green-500';
  };

  const getStatusText = () => {
    if (!isOnline) return 'غير متصل';
    if (syncInProgress) return 'جاري المزامنة...';
    if (pendingChanges > 0) return `${pendingChanges} عنصر معلق`;
    return 'متزامن';
  };

  const getSyncIcon = () => {
    switch (syncStatus) {
      case 'syncing':
        return <RefreshCw className="h-4 w-4 animate-spin" />;
      case 'success':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'error':
        return <AlertCircle className="h-4 w-4 text-red-600" />;
      default:
        return <RotateCcw className="h-4 w-4" />;
    }
  };

  return (
    <div className="fixed bottom-4 right-4 z-50">
      <Card className="shadow-lg border-2" style={{ borderColor: isOnline ? '#10b981' : '#ef4444' }}>
        <CardContent className="p-3">
          <div className="flex items-center gap-3">
            {/* Status Indicator */}
            <div className="flex items-center gap-2">
              {isOnline ? (
                <Wifi className="h-5 w-5 text-green-600" />
              ) : (
                <WifiOff className="h-5 w-5 text-red-600" />
              )}
              <Badge className={`text-white ${getStatusColor()}`}>
                {getStatusText()}
              </Badge>
            </div>

            {/* Action Buttons */}
            <div className="flex items-center gap-1">
              {isOnline && pendingChanges > 0 && (
                <Button
                  size="sm"
                  variant="outline"
                  onClick={handleManualSync}
                  disabled={syncStatus === 'syncing'}
                  className="h-8 px-2"
                >
                  {getSyncIcon()}
                </Button>
              )}
              
              <Button
                size="sm"
                variant="outline"
                onClick={() => setShowDetails(!showDetails)}
                className="h-8 px-2"
              >
                <Database className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* Detailed Status */}
          {showDetails && (
            <div className="mt-3 pt-3 border-t space-y-2 text-sm">
              <div className="flex justify-between items-center">
                <span>حالة التخزين المؤقت:</span>
                <Badge variant={cacheStatus === 'ready' ? 'default' : 'secondary'}>
                  {cacheStatus === 'ready' ? 'جاهز' : 
                   cacheStatus === 'empty' ? 'فارغ' : 
                   cacheStatus === 'unsupported' ? 'غير مدعوم' : 'خطأ'}
                </Badge>
              </div>
              
              {lastSync && (
                <div className="flex justify-between items-center">
                  <span>آخر مزامنة:</span>
                  <span className="text-xs text-gray-600 flex items-center gap-1">
                    <Clock className="h-3 w-3" />
                    {lastSync.toLocaleTimeString('ar-AE')}
                  </span>
                </div>
              )}
              
              <div className="flex justify-between items-center">
                <span>العمليات المعلقة:</span>
                <Badge variant={syncStats.pendingOperations > 0 ? 'destructive' : 'default'}>
                  {syncStats.pendingOperations || 0}
                </Badge>
              </div>
              
              <div className="flex justify-between items-center">
                <span>السجلات المعلقة:</span>
                <Badge variant={syncStats.recordsNeedingSync > 0 ? 'destructive' : 'default'}>
                  {syncStats.recordsNeedingSync || 0}
                </Badge>
              </div>
              
              <div className="flex justify-between items-center">
                <span>الإجراءات غير المعالجة:</span>
                <Badge variant={syncStats.unprocessedActions > 0 ? 'destructive' : 'default'}>
                  {syncStats.unprocessedActions || 0}
                </Badge>
              </div>

              {/* Action Buttons */}
              <div className="flex gap-2 pt-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    checkCacheStatus();
                    loadSyncStatistics();
                  }}
                  className="flex-1 text-xs"
                >
                  <RefreshCw className="h-3 w-3 mr-1" />
                  تحديث
                </Button>
                
                <Button
                  size="sm"
                  variant="outline"
                  onClick={clearCache}
                  className="flex-1 text-xs"
                >
                  <Download className="h-3 w-3 mr-1" />
                  مسح التخزين
                </Button>
              </div>

              {/* Offline Instructions */}
              {!isOnline && (
                <div className="mt-2 p-2 bg-yellow-50 rounded text-xs">
                  <p className="text-yellow-800 font-medium">وضع عدم الاتصال</p>
                  <p className="text-yellow-700">
                    يمكنك الاستمرار في العمل. سيتم حفظ التغييرات محلياً ومزامنتها عند الاتصال بالإنترنت.
                  </p>
                </div>
              )}

              {/* Sync Status Messages */}
              {syncStatus === 'syncing' && (
                <div className="mt-2 p-2 bg-blue-50 rounded text-xs">
                  <p className="text-blue-800">جاري المزامنة...</p>
                </div>
              )}

              {syncStatus === 'success' && (
                <div className="mt-2 p-2 bg-green-50 rounded text-xs">
                  <p className="text-green-800">تمت المزامنة بنجاح</p>
                </div>
              )}

              {syncStatus === 'error' && (
                <div className="mt-2 p-2 bg-red-50 rounded text-xs">
                  <p className="text-red-800">فشلت المزامنة. حاول مرة أخرى.</p>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default EnhancedOfflineStatus;
